<script lang="ts">
	import { onMount } from 'svelte';
	import { request } from './api';
	import { PageHeader, RefreshButton } from './ui';
	type Message={id:string;body:string;created_at:string;author_name:string;file_id:string|null};
	type Thread={id:string;title:string;kind:string;created_at:string;members:{id:string;full_name:string;role:string}[];messages:Message[]};
	let threads=$state<Thread[]>([]), selected=$state(''), title=$state(''), kind=$state('group'), body=$state(''), error=$state(''), loading=$state(true), saving=$state(false);
	let active=$derived(threads.find(thread=>thread.id===selected)??threads[0]);
	async function load(){loading=true;error='';try{threads=await request<Thread[]>('/v1/admin/collaboration');selected||=(threads[0]?.id??'');}catch(cause){error=cause instanceof Error?cause.message:'Kolaborasi tidak dapat dimuat.';}finally{loading=false;}}
	async function create(){saving=true;error='';try{await request('/v1/admin/collaboration',{method:'POST',body:JSON.stringify({title,kind,member_ids:[]})});title='';await load();}catch(cause){error=cause instanceof Error?cause.message:'Ruang tidak dapat dibuat.';}finally{saving=false;}}
	async function send(){if(!active)return;saving=true;error='';try{await request(`/v1/admin/collaboration/${active.id}/messages`,{method:'POST',body:JSON.stringify({body,file_id:null})});body='';await load();}catch(cause){error=cause instanceof Error?cause.message:'Pesan tidak dapat dikirim.';}finally{saving=false;}}
	onMount(load);
</script>
<svelte:head><title>Collaboration · PasPapan</title></svelte:head>
<main class="workspace-page" id="main-content" tabindex="-1"><PageHeader title="Collaboration" description="Ruang percakapan kerja yang ringkas, terarah, dan terisolasi per perusahaan." backHref="/admin/dashboard"/>
{#if error}<p class="alert" role="alert">{error} <RefreshButton onclick={load} label="Coba lagi"/></p>{/if}
<section class="layout" aria-busy={loading}><aside class="panel"><form novalidate onsubmit={(event)=>{event.preventDefault();create();}}><h2>Ruang baru</h2><input bind:value={title} placeholder="Nama ruang" maxlength="180" required/><select bind:value={kind}><option value="group">Tim</option><option value="project">Proyek</option><option value="personal">Pribadi</option></select><button disabled={saving}>Buat ruang</button></form><nav aria-label="Daftar ruang">{#each threads as thread (thread.id)}<button class:chosen={active?.id===thread.id} onclick={()=>selected=thread.id}><strong>{thread.title}</strong><small>{thread.kind} · {thread.members.length} anggota</small></button>{/each}</nav></aside>
<section class="panel conversation">{#if active}<header><div><h2>{active.title}</h2><p>{active.members.map(member=>member.full_name).join(', ')}</p></div><RefreshButton onclick={load} label="Muat ulang"/></header><div class="messages">{#if !active.messages.length}<p class="muted">Belum ada pesan.</p>{:else}{#each active.messages as message (message.id)}<article><strong>{message.author_name}</strong><p>{message.body}</p><small>{new Date(message.created_at).toLocaleString('id-ID')}</small></article>{/each}{/if}</div><form novalidate onsubmit={(event)=>{event.preventDefault();send();}}><textarea bind:value={body} placeholder="Tulis pesan…" maxlength="5000" required></textarea><button disabled={saving}>Kirim</button></form>{:else}<p class="muted">Buat ruang untuk memulai kolaborasi.</p>{/if}</section></section></main>
<style>.workspace-page{display:grid;gap:12px}.layout{display:grid;grid-template-columns:300px minmax(0,1fr);gap:12px}.panel{padding:16px;border-radius:var(--radius)}form{display:grid;gap:8px}h2{font-size:15px;margin:0}aside nav{display:grid;gap:5px;margin-top:16px}aside nav button{text-align:left;padding:10px;border:1px solid var(--line);background:var(--surface-alt)}aside nav button.chosen{border-color:var(--accent);background:color-mix(in srgb,var(--accent) 12%,var(--surface))}small,p{color:var(--muted);font-size:11px}small{display:block;margin-top:2px}.conversation{display:grid;gap:12px}.conversation header{display:flex;justify-content:space-between;gap:10px}.conversation header p{margin:4px 0 0}.messages{display:grid;gap:8px;min-height:280px;align-content:start}.messages article{padding:10px;border:1px solid var(--line);border-radius:var(--radius-sm);font-size:12px}.messages article p{color:var(--text);margin:5px 0}.conversation textarea{min-height:72px;resize:vertical}.alert{margin:0;color:var(--danger);font-size:12px}@media(max-width:720px){.layout{grid-template-columns:1fr}.messages{min-height:180px}}</style>
